use cuemol_molstr::{read_mol2_str, BondOrder};

#[test]
fn mol2_reader_matches_reference_basic_records() {
    let input = "\
# generated by mol2 writer
@<TRIPOS>MOLECULE
ligand
3 2 1 0 0
SMALL
USER_CHARGES
@<TRIPOS>ATOM
1 N 0.0 0.0 0.0 N.am 1 LIG -0.6
2 CA 1.0 0.0 0.0 C.3 1 LIG 0.2
3 O 1.0 1.0 0.0 O.2 1 LIG -0.4
@<TRIPOS>BOND
1 1 2 1
2 2 3 am
";
    let mol = read_mol2_str(input).unwrap();
    assert_eq!(mol.atom_count(), 3);
    assert_eq!(mol.bond_count(), 2);
    assert_eq!(mol.atoms()[0].name, "N");
    assert_eq!(mol.atoms()[0].element, "N");
    assert_eq!(mol.atoms()[0].res_name, "LIG");
    assert_eq!(mol.atoms()[0].chain_id, "A");
    assert_eq!(mol.bonds()[1].order, BondOrder::Aromatic);
}

#[test]
fn mol2_reader_handles_multiple_molecules_and_duplicate_names() {
    let input = "\
@<TRIPOS>MOLECULE
first
2 0 0 0 0
SMALL
USER_CHARGES
@<TRIPOS>ATOM
1 C 0.0 0.0 0.0 C.3 1 <0> 0.0
2 C 1.0 0.0 0.0 C.3 1 <0> 0.0
@<TRIPOS>MOLECULE
second
1 0 0 0 0
SMALL
USER_CHARGES
@<TRIPOS>ATOM
1 O 0.0 1.0 0.0 O.2 1 RES 0.0
";
    let mol = read_mol2_str(input).unwrap();
    assert_eq!(mol.atom_count(), 3);
    assert_eq!(mol.atoms()[0].res_name, "first");
    assert_eq!(mol.atoms()[1].name, "2C");
    assert_eq!(mol.atoms()[2].chain_id, "02_A");
}
